SELECT name
FROM products
WHERE price < 500;

SELECT name
FROM customers
WHERE city = 'Москва';

SELECT name
FROM products
WHERE category = 'Электроника';

SELECT name, stock
FROM products
WHERE stock < 30;

SELECT name, price, stock
FROM products
WHERE price > 5000 AND stock < 30;

SELECT name
FROM products
WHERE category <> 'Мебель';

SELECT name, price
FROM products
WHERE price BETWEEN 1000 AND 5000;

SELECT name, city
FROM customers
WHERE city IN ('Москва', 'Казань');

SELECT name
FROM products
WHERE name LIKE 'Т%';

SELECT name
FROM products
WHERE name LIKE '%ь%';

SELECT category, COUNT(*) AS n
FROM products
GROUP BY category;

SELECT city, COUNT(*) AS n
FROM customers
GROUP BY city;

SELECT city, AVG(age) AS avg_age
FROM customers
GROUP BY city;

SELECT *
FROM users
WHERE city = 'Москва';

SELECT *
FROM users
ORDER BY age DESC;
